/// True when `key` belongs to ComposeMapArt.
bool IsMapArtKey(std::string_view key);
/// Composes a Map page key (see dq3_map.cpp). `astc` decodes ASTC 8x8 blocks.
std::optional<Image> ComposeMapArt(const RangeReader& read, std::string_view key,
                                   const AstcFn& astc,
                                   std::string* why = nullptr);

